    if (venta && (fin - cambio <= 30 * DIA || fin - t(o) <= 30 * DIA)) r.vMes++;
  }
  const filasAg = Object.entries(porAgente).filter(([, r]) => r.cot || r.vMes).sort((a, b) => (b[1].cot + b[1].vMes) - (a[1].cot + a[1].vMes));
  if (filasAg.length) h += `<h3 style="${S.h3}">Cotizados y vendidos por agente</h3>` + tabla(['Agente', 'En cotización (último mes)', 'Sin avanzar +3 días', 'Vendidos esta semana', 'Vendidos último mes', '% cierre (mes)'],
    filasAg.map(([k, r]) => [k, r.cot, r.quietas ? `<b style="color:#9a6700">${r.quietas}</b>` : 0, r.vSem ? `<b style="color:#1a7f37">${r.vSem}</b>` : 0, r.vMes, pct(r.vMes, r.cot + r.vMes) + ' %']))
    + `<p style="font-size:12px;color:#666;margin:4px 0 0">Vendido = con anticipo o pagado completo. % cierre = vendidos ÷ (en cotización + vendidos) del último mes.</p>`;
  h += `<h3 style="${S.h3}">¿De dónde llegan?</h3>` + tabla(['Canal', 'Leads', 'Dieron sus datos'], top(Object.fromEntries(Object.entries(porCanal).map(([k, v]) => [k, v.n])), 8).map(([k]) => [k, porCanal[k].n, pct(porCanal[k].ok, porCanal[k].n) + ' %']));
  if (ads.length) h += `<h3 style="${S.h3}">Anuncios que más clientes trajeron</h3>` + tabla(['Anuncio / promo', 'Leads', 'Dieron sus datos'], ads.slice(0, 6).map(([k, v]) => [k, v.n, pct(v.ok, v.n) + ' %']));
  const td5 = top(destinos, 6), tm = top(meses, 4);
  const totD = Object.values(destinos).reduce((s, v) => s + v, 0);
  const th8 = Object.entries(hoteles).sort((a, b) => b[1].n - a[1].n).slice(0, 8), totH = Object.values(hoteles).reduce((s, v) => s + v.n, 0);
  if (td5.length || th8.length) {
    h += `<h3 style="${S.h3}">Lo que piden tus clientes</h3>`;
    if (td5.length) h += `<p style="margin:6px 0 4px"><b>Por destino</b></p>` + tabla(['Destino', 'Clientes', '%'], td5.map(([k, v]) => [k, v, pct(v, totD) + ' %']));
    if (th8.length) h += `<p style="margin:12px 0 4px"><b>Por hotel</b></p>` + tabla(['Hotel', 'Destino', 'Clientes', '%'], th8.map(([k, v]) => [k, v.destino.replace(' / Zihuatanejo', ''), v.n, pct(v.n, totH) + ' %']))
      + `<p style="font-size:12px;color:#666;margin:4px 0 0">Hotel que el cliente pidió al escribir, o el de la promo del anuncio por el que llegó si no nombró ninguno.</p>`;
    if (tm.length) h += `<p style="margin:12px 0 0"><b>Quieren viajar en:</b> ${tm.map(([k, v]) => `${k} (${v})`).join(' · ')}</p>`;
  }
  if (sem.length) h += `<h3 style="${S.h3}">¿Cuándo escriben?</h3><p style="margin:0 0 4px">${Object.entries(franjas).map(([k, v]) => `${k}: <b>${pct(v, sem.length)} %</b>`).join(' · ')}</p><p style="margin:0">Días con más mensajes: ${top(porDiaSem, 3).map(([k, v]) => `${k} (${v})`).join(', ')}</p>`;
  h += `<p style="font-size:12px;color:#777;margin:22px 0 0">Reporte automático de tu asesora IA. "Dieron sus datos" = el cliente dio destino, fechas y personas y pasó a cotización.</p></div>`;
  salida.push({ json: { agencia: ag, para: cfg.para, asunto: `📊 ${cfg.nombre}: ${sem.length} clientes nuevos, ${tasaGlobal} % listos para cotizar (semana del ${fmt(ini)})`, html: h } });
}
return salida;
